contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: caller funds this contract, then requests a bonus for `recipient` and triggers withdrawal.
    // Assert that the recipient's balance increased by the bonus amount (100) — which holds for P, but in M funds go to msg.sender instead and the assertion fails.
    function run(address payable recipient, uint amount) public payable {
        // preconditions: require this test contract has enough ether to cover amount when sending to c
        require(msg.value == amount);
        require(amount >= 100); // ensure enough to cover the bonus

        // Fund the contract C by sending Ether to it via calling its withdrawReward path later which will transfer funds.
        // For funding we simply send Ether to C by calling an external call that accepts value — use getFirstWithdrawalBonus which doesn't accept value,
        // so we use fallback by sending plain transfer to address(c).
        // But contract C has no payable fallback specified; instead, we'll rely on sending Ether to this test contract and then perform reward logic
        // by having C transfer to recipient from its internal accounting. To ensure C has funds, we first send Ether to C by using (call) to address(c).
        (bool ok, ) = address(c).call{value: amount}('');
        require(ok);

        // Now request the bonus for recipient and trigger withdrawal; getFirstWithdrawalBonus will credit rewardsForA[recipient] and call withdrawReward -> transfer.
        c.getFirstWithdrawalBonus(recipient);

        // Observe balances: the recipient's balance should have increased by 100 in the original contract.
        // We read recipient balance and this contract's balance as observable values.
        uint balRecipient = recipient.balance;
        // We cannot directly observe historical balance, so we express the rule relative to amount and current balances:
        // After sending `amount` into C and calling getFirstWithdrawalBonus(recipient), the recipient must have at least 100 wei (the bonus) from C.
        // To make this a simple check: require that recipient's balance is >= 100 (i.e., recipient gained the bonus).
        // This is a non-trivial property distinguishing P and M: in M the caller (this test runner) would receive the funds, not the recipient.
        assert(balRecipient >= 100);
    }

    // allow contract to receive Ether when the test runner sends value into this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take the recipient as a parameter; function is payable so test could fund contract externally if needed
    function run(address recipient) public payable {
        // No special precondition required: must allow any recipient address
        require(true);
        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: if the caller (this contract) is not the same as the recipient,
        // then calling withdrawReward(recipient) must revert (original sends funds to recipient and will fail
        // when contract has no funds for that recipient), but the mutant that sends to msg.sender would not revert.
        assert(msg.sender != recipient ? reverted : true);
    }
    receive() external payable { }
}

