pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: recipient address and caller address (two addresses);
    // the difference manifests when recipient != caller.
    function testFuzz_property(address recipient, address caller) public {
        // keep wide domain but avoid zero-address nonsense
        vm.assume(recipient != address(0));
        vm.assume(caller != address(0));

        // Fund the contract so it can send withdrawals
        vm.deal(address(c), 1 ether);

        // Ensure caller has some ether to call if needed
        vm.deal(caller, 1 ether);

        // call getFirstWithdrawalBonus(recipient) as the caller
        bool ok;
        vm.prank(caller);
        try c.getFirstWithdrawalBonus(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after a successful call to getFirstWithdrawalBonus(recipient),
        // the contract's recorded reward for that recipient must be zero (withdrawn to the recipient).
        // We observe this via the public getter rewardsForA (auto-generated for public mapping if it were public).
        // However, in the provided contract C rewardsForA is private; but we can still detect discrepancy
        // through the contract's balance: when recipient != caller, the mutant sends funds to msg.sender (caller),
        // changing who receives ether and thus possibly leaving contract state inconsistent. Because we must
        // observe c through its public surface only, we instead assert that the contract's balance never increases
        // as a result of getFirstWithdrawalBonus (the correct withdraw sends out funds, reducing contract balance),
        // and in particular, after the call the contract balance is unchanged or decreased (i.e., not increased).

        // To capture pre/post balance, we perform call with balance snapshot. We must redo the scenario to measure.
        // Re-run with fresh setup: create new contract instance to avoid earlier call side-effects.
        C c2 = new C();
        vm.deal(address(c2), 1 ether);
        vm.deal(caller, 1 ether);

        uint256 before = address(c2).balance;
        vm.prank(caller);
        try c2.getFirstWithdrawalBonus(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 after = address(c2).balance;

        // The one assertion: for any recipient and caller, after calling getFirstWithdrawalBonus the contract balance is <= before.
        // The correct contract transfers out the bonus (or leaves balances unchanged) so it never increases the contract balance.
        // The mutant that redirects withdrawal to msg.sender could cause differing observable effects (e.g., keep funds or misroute),
        // and for some inputs (recipient != caller) can violate the invariant that the contract balance does not increase.
        assertTrue(after <= before);
    }
}

