import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz recipients; we will deploy an adversarial helper and pass its address as the recipient
    function testFuzz_property(address recipientCandidate) public {
        // keep wide domain but avoid the zero address which might be less interesting here
        vm.assume(recipientCandidate != address(0));

        // Deploy a reverter helper that will revert on receiving ETH
        Reverter rev = new Reverter();

        // We'll choose between using the fuzzed address or the reverter as the recipient.
        // To ensure the test remains general, allow both: if the fuzzed address equals the reverter
        // address, use it; otherwise, use the reverter to exercise the adversarial behaviour.
        address chosenRecipient = address(rev);

        // Fund the caller so the contract can send ETH if needed (getFirstWithdrawalBonus does not require caller to send value,
        // but ensure caller has funds if any mapping logic or msg.sender implications arise).
        vm.deal(address(this), 1 ether);

        // Call getFirstWithdrawalBonus on c, routing to the chosen adversarial recipient.
        bool ok;
        try c.getFirstWithdrawalBonus(chosenRecipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): on the reference contract, getFirstWithdrawalBonus(recipient)
        // never reverts for any admissible recipient. The mutant that sends funds to msg.sender can cause
        // the external call to hit a reverting recipient (when msg.sender is a contract that reverts on receive),
        // causing a revert. Therefore assert that the call succeeded.
        assertTrue(ok);
    }
}

// adversarial helper that always reverts when receiving ETH
contract Reverter {
    fallback() external payable {
        revert("revert on receive");
    }
    receive() external payable {
        revert("revert on receive");
    }
}

