import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { 
        c = new C();
        attacker = new Attacker(address(c));
    }

    // Fuzzed params: initial reward amount and a boolean deciding whether attacker will reenter
    function testFuzz_property(uint256 initialReward, bool willReenter) public {
        // keep reward reasonable to avoid overflow in test harness but wide
        uint256 reward = bound(initialReward, 0, 1e18);

        // fund the contract so it can pay out
        vm.deal(address(this), 1e18);
        // send funds into c so it has balance to pay
        payable(address(c)).transfer(reward + 1);

        // set up the reward for the attacker address in the mapping by calling getFirstWithdrawalBonus
        // We need to call getFirstWithdrawalBonus on the attacker address, which will add 100 and then call withdrawReward
        // To directly set rewardsForA we call getFirstWithdrawalBonus with the attacker address as recipient.

        // ensure attacker has code at its address (we deployed it already)
        // Configure attacker whether to reenter when receiving funds
        attacker.setReenter(willReenter);

        // Call getFirstWithdrawalBonus to add bonus and cause withdrawReward(recipient) to be invoked
        // We call it from this contract but the recipient is the attacker contract
        c.getFirstWithdrawalBonus(address(attacker));

        // After the withdrawReward call completes, the invariant in the correct contract is that rewardsForA[attacker] == 0
        // We observe this by calling the autogenerated getter for rewardsForA which is named rewardsForA in original contract
        // However rewardsForA is private in the given source; since mappings are private, there is no getter.
        // The problem statement allows reading public getters only. But we can infer state difference by repeating withdrawReward:
        // If rewardsForA[attacker] was zeroed, a subsequent withdrawReward should send 0 and succeed (no extra funds paid),
        // while if rewardsForA was not zeroed because reentrancy happened, a subsequent withdrawReward would attempt to send the leftover amount and (depending on attacker behavior) may reenter or cause different balance effects.

        // We'll observe behavior by invoking withdrawReward again and catching whether it succeeds (ok==true) or reverts (ok==false).
        // For the correct contract, the second call should succeed (sending 0 value) and not revert; for the mutant, attacker may cause unexpected non-zero transfer attempt and change outcome.

        bool ok;
        try c.withdrawReward(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: reference guarantees the second call to withdrawReward for the same recipient succeeds (sends zero) for all inputs; the mutant is breakable by the reentrant attacker for some inputs
        assertTrue(ok);
    }
}

