pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: amount to seed as reward (uint256) and a boolean whether the helper should reenter
    function testFuzz_property(uint256 seedReward, bool doReenter) public {
        // keep reward to a reasonable bound to avoid extremely large transfers
        uint256 reward = bound(seedReward, 0, 1 ether);

        // Deploy a malicious recipient that will attempt reentrancy during receive()
        ReentrantRecipient attacker = new ReentrantRecipient(address(c));
        address recipient = address(attacker);

        // fund C so that withdrawReward can actually send value
        vm.deal(address(c), 2 ether);

        // seed the private mapping rewardsForA by using getFirstWithdrawalBonus which increments by 100
        // but we also directly set up attacker to have an initial reward via making a direct call to withdrawReward's storage path
        // we cannot write to private mapping, so instead we rely on getFirstWithdrawalBonus to add and then call withdraw

        // If doReenter is true, attacker will reenter during its fallback/receive to call withdrawReward again.
        attacker.setReenter(doReenter);

        // Give attacker some Ether so their fallback can execute and send/receive if needed
        vm.deal(recipient, 1 ether);

        // Now call getFirstWithdrawalBonus which in C adds 100 to rewardsForA[recipient], then calls withdrawReward(recipient)
        // For the reference contract, rewardsForA[recipient] will end up 0 after getFirstWithdrawalBonus returns for all inputs
        // For the mutant that zeroes after the external call, if the recipient reenters and manipulates state during the external call,
        // rewardsForA[recipient] may remain non-zero.

        // Call as any EOA (test contract) to drive the logic
        c.getFirstWithdrawalBonus(recipient);

        // Exactly one assertion reading c's public surface: check that rewardsForA[recipient] == 0 via observing behavior.
        // rewardsForA is private; however, its effect is observable because another withdrawReward call will send zero value
        // if rewardsForA[recipient] == 0, then calling withdrawReward(recipient) should succeed but transfer 0 (no revert)
        // To observe stored value, we attempt a withdrawReward and then check that C's balance didn't decrease.

        uint256 balanceBefore = address(c).balance;
        bool ok;
        try c.withdrawReward(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balanceAfter = address(c).balance;

        // For the reference contract, after initial getFirstWithdrawalBonus, rewards were zeroed, so second withdraw sends 0 and does not change contract balance (and does not revert).
        // Thus ok must be true and balanceAfter == balanceBefore.
        assertTrue(ok && balanceAfter == balanceBefore);
    }
}

// Minimal reentrant recipient: on receiving funds it may call back into C.withdrawReward
contract ReentrantRecipient {
    address public target;
    bool public reenter;

    constructor(address _target) payable {
        target = _target;
        reenter = false;
    }

    function setReenter(bool r) external {
        reenter = r;
    }

    receive() external payable {
        if (reenter) {
            // attempt reentrancy by calling withdrawReward again
            // ignore failures
            try C(target).withdrawReward(address(this)) {
            } catch {
            }
        }
    }
}

