pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter: amount to pay into the contract and then attempt withdrawal for the attacker
    function testFuzz_property(uint256 seedAmount) public {
        // keep amount within reasonable bounds but wide: at least 1 wei and not absurdly large
        uint256 amount = bound(seedAmount, 1, 1 ether);

        // Deploy an adversarial callee that will accept funds but revert on calldata-free calls
        MaliciousReverter mal = new MaliciousReverter();

        // Fund the contract's internal rewards mapping by calling getFirstWithdrawalBonus targeting the malicious address
        // getFirstWithdrawalBonus will credit rewardsForA[mal] += 100 and call withdrawReward(mal)
        // But to ensure withdrawReward has a positive reward amount, we first directly set a reward by sending funds
        // We emulate funding by directly calling into the contract's payable entrypoint via vm.prank on an EOA.

        // Give the contract ETH so it can pay out
        vm.deal(address(this), amount + 1 ether);
        // Fund the contract so that when withdrawReward tries to send value, contract has balance
        (bool sent,) = address(c).call{value: amount + 100}(
            abi.encodeWithSignature("getFirstWithdrawalBonus(address)", address(mal))
        );
        // The reference contract should succeed in its internal sequence; if this call reverted, we still continue to observe behavior via getter

        // Now attempt to explicitly call withdrawReward to trigger external call to the malicious callee
        bool ok;
        try c.withdrawReward(address(mal)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after calling withdrawReward on the reference, rewardsForA[mal] must be zero.
        // We observe via the public getter rewardsForA(address) — mapping was private in original but assume C exposes it as public per problem statement.
        // The single assertion below reads contract state; on the correct contract it holds for all inputs; the mutant can violate it.
        assertTrue(c.rewardsForA(address(mal)) == 0);
    }
}

// adversarial callee: accepts ETH but reverts on plain calls to force difference in ordering effects
contract MaliciousReverter {
    // accept plain ETH transfers
    receive() external payable {}
    // fallback will revert to simulate a callee that causes the external call to revert
    fallback() external payable {
        revert("malicious revert");
    }
}

