import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: attacker initial balance and bonus triggering address (we deploy attacker contract so address param isn't used as an EOA)
    function testFuzz_property(uint256 attackerFunds, address /*unusedRecipientAddr*/) public {
        // keep funds in a reasonable range but wide
        attackerFunds = bound(attackerFunds, 1, 1 ether);

        // deploy adversarial reentrant recipient that will call back into c during receive
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // fund attacker so it can receive and send value
        vm.deal(address(attacker), attackerFunds);

        // The property: after getFirstWithdrawalBonus(attacker) completes, rewardsForA[attacker] == 0
        // Drive the interaction: attacker will be passed as recipient
        // We call getFirstWithdrawalBonus which in reference: increments rewardsForA, zeroes it in withdrawReward before external call, so final getter == 0
        // The mutant that zeroes after the external call can be reentered by attacker to disturb state and leave a non-zero value

        // call through the attacker: attacker will invoke c.getFirstWithdrawalBonus(address(attacker))
        attacker.triggerGetFirstWithdrawalBonus{value: 0}(attackerFunds);

        // exactly one assertion reading c's public surface: mapping rewardsForA has public getter in original C; but in provided C it's private.
        // The original problem statement mentions rewardsForA as private in source; however the intended observable is that after withdrawal the mapping is zero — since mapping is private we cannot read it.
        // To comply with rule (must read c through public surface), we instead observe that after getFirstWithdrawalBonus completes, address(c).balance decreased by the withdrawn amount in reference
        // But address(c).balance is a valid public surface. We compute expected: reference withdraws amount and sends funds to recipient, so c balance should be unchanged if it had none and the call uses internal funds — to ensure distinction we fund c first.

        // To make the difference observable via address(c).balance across reference vs mutant, fund contract then call getFirstWithdrawalBonus which triggers withdrawReward sending value out.
        // Re-deploy fresh C, fund it, and redo with attacker to assert on address(c).balance.
        C c2 = new C();
        vm.deal(address(c2), 1 ether);
        ReentrantAttacker attacker2 = new ReentrantAttacker(c2);
        vm.deal(address(attacker2), attackerFunds);

        // attacker triggers bonus which will call withdrawReward and transfer out 100 wei (as per reference implementation)
        attacker2.triggerGetFirstWithdrawalBonus{value: 0}(attackerFunds);

        // After correct contract completes, it must have sent the reward out, so its balance decreased by 100 (the bonus amount in reference)
        // Assert the invariant: c2 balance is exactly 1 ether - 100
        // This is a single assertTrue observing c's public surface (address(c2).balance)
        assertTrue(address(c2).balance == (1 ether - 100));
    }
}

// Minimal reentrant attacker: when it receives value it will try to reenter withdrawReward to exploit mutant behavior.
contract ReentrantAttacker {
    C public target;
    bool public reentered;

    constructor(C _target) payable {
        target = _target;
    }

    // Called from test to start the flow: we call getFirstWithdrawalBonus on target with our own address
    function triggerGetFirstWithdrawalBonus(uint256 /*unused*/) external {
        // call target.getFirstWithdrawalBonus with our address as recipient
        target.getFirstWithdrawalBonus(address(this));
    }

    // receive will be invoked by target.withdrawReward; on first receive we attempt to reenter withdrawReward to disturb mutant
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // try to reenter withdrawReward
            // use try/catch to avoid bubbling reverts to test
            try target.withdrawReward(address(this)) {
            } catch {}
        }
    }
}

