        // keep seedReward in a reasonable range so calls can send value
        seedReward = bound(seedReward, 0, 1 ether);
        // avoid zero address owner for prank purposes
        vm.assume(attackerOwner != address(0));

        // Deploy a reentrant attacker that will, when receiving ETH, reenter withdrawReward on c
        Attacker atk = new Attacker(c);

        // fund the contract c so it can pay out rewards
        vm.deal(address(c), 2 ether);

        // set up initial reward mapping by calling a function that gives reward
        // We don't have a public setter; but getFirstWithdrawalBonus adds 100 and then withdraws
        // To put arbitrary reward into rewardsForA we can simulate by calling withdrawReward for a recipient that has rewardsForA set via getFirstWithdrawalBonus
        // To place seedReward into rewardsForA[atk], we'll mimic by directly making the contract think there's that reward by performing a sequence:
        // - First, ensure attacker has not claimed bonus so getFirstWithdrawalBonus will add 100 and call withdraw. But we need arbitrary seedReward. Since we can't write private mapping, we instead rely on the following admissible approach:
        // Use the fact that withdrawReward reads rewardsForA[recipient] then sends that amount; to set a nonzero amount we need to manipulate the mapping via getFirstWithdrawalBonus which adds 100. To get more varied values, call getFirstWithdrawalBonus multiple times from different addresses is not possible because of claimedBonus mapping. Therefore, we seed with at least 100 when seedReward == 0, otherwise we top up contract balance and rely on seedReward being within bounds and use the attacker to reenter during withdraw to cause the mutant to break.
        // Simpler: use seedReward only to decide whether to trigger the reentrancy or not; the observable property is that after withdrawReward(attacker) completes, rewardsForA[attacker] == 0 in reference but may be nonzero in mutant. We'll ensure the mapping has a nonzero value by first calling getFirstWithdrawalBonus on the attacker to set rewardsForA[attacker] += 100 and then rely on reentrant behavior to demonstrate difference when seedReward>0 triggers additional path.

        // Ensure attacker hasn't claimed and has reward: call getFirstWithdrawalBonus for atk
        // The attacker contract has a function to forward calls from this test (non-payable)
        // call getFirstWithdrawalBonus with attacker's address
        c.getFirstWithdrawalBonus(address(atk));

        // Now rewardsForA[address(atk)] should be 0 in reference after getFirstWithdrawalBonus completes (because it withdraws), but the difference manifests if attacker reenters during withdrawReward and causes rewardsForA to be set differently. To trigger the reentrancy, set seedReward > 0 to indicate we want the attacker to reenter.

        // fund the attacker so it can receive and reenter
        vm.deal(address(atk), 0);

        // If seedReward is zero we still attempt a normal withdraw; if nonzero attacker will attempt reentry when receiving funds
        // Set the attacker behavior based on seedReward: use its toggleReenter function
        if (seedReward % 2 == 1) {
            atk.enableReenter();
        } else {
            atk.disableReenter();
        }

        // Now call withdrawReward targeting the attacker address so its fallback/receive will be invoked
        // We must send no msg.value; withdrawReward uses contract balance to pay
        bool ok;
        try c.withdrawReward(address(atk)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property to assert: after withdrawReward completes (succeeds or not), the reference contract always has rewardsForA[atk] == 0.
        // Observe via public getter: rewardsForA has no public getter in original, but the problem statement allowed reading c's public surface; however rewardsForA was private in given code; to follow the requirement we must observe some public behavior. The contract C as provided has no public getter for rewardsForA. But the difference described is that the mapping differs — the accessible indicator is getFirstWithdrawalBonus behavior or ability to withdraw again.
        // Instead, we assert that a second call to withdrawReward(attacker) will revert (or succeed) consistently: in the correct contract, after first withdrawReward completed, calling withdrawReward again with same recipient and no new reward should attempt to send 0 value and succeed (sending 0 value to an address with payable fallback does not revert) and results in no change. However the mutant may leave a nonzero reward causing the second call to attempt sending nonzero and possibly trigger reentrancy/revert.
        // To make a direct public observation, we'll attempt the second withdraw and observe that it does NOT revert on the correct contract for any inputs (it should succeed sending 0 value), but the mutant can cause a revert due to reentrancy or other state. So we assert that the second withdraw does not revert.

        bool ok2;
        try c.withdrawReward(address(atk)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Single assertTrue reading c's behavior: the reference guarantees second call does not revert (ok2 == true) for all inputs; the mutant can leave a nonzero reward and cause ok2 == false for some input (attacker reentrancy).
        assertTrue(ok2);
    }
}

// Minimal attacker: on receive it can reenter withdrawReward once
contract Attacker {
    C public target;
    bool public reenterAllowed = false;
    bool public reentered = false;

    constructor(C _t) {
        target = _t;
    }

    function enableReenter() external { reenterAllowed = true; }
    function disableReenter() external { reenterAllowed = false; }

    receive() external payable {
        if (reenterAllowed && !reentered) {
            reentered = true;
            // reenter withdrawReward on target
            // ignore failures
            try target.withdrawReward(address(this)) {
            } catch {
            }
        }
    }
}

