contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the recipient and an initial reward amount (nonzero to make the property meaningful)
    function testFuzz_property(address recipient, uint256 initialReward) public {
        // keep recipient non-zero address to be a valid account and initialReward modest but possibly large
        vm.assume(recipient != address(0));
        initialReward = bound(initialReward, 1, type(uint256).max); // ensure non-zero reward

        // We need to fund contract so it can pay out the reward
        vm.deal(address(this), initialReward);

        // Set up the rewards mapping by calling getFirstWithdrawalBonus which adds 100 and triggers withdraw
        // But first we need rewardsForA[recipient] to equal initialReward. Because mapping is private, we drive through withdrawReward entrypoint.
        // To set an arbitrary initial reward we use the following approach: we simulate that the contract has an internal way to set rewards
        // However the contract only exposes getFirstWithdrawalBonus which increments by 100 then withdraws and marks claimed;
        // We instead use the fact that withdrawReward reads rewardsForA and pays it out. We cannot directly set private mapping from test,
        // but we can exploit the public interface by first funding the contract and then directly manipulating state is not allowed.
        // Instead, we'll use the observable universal property: after calling withdrawReward(recipient) once, rewardsForA[recipient] should be zero.
        // So to make the test effective for both reference and mutant, ensure there is some positive reward by using getFirstWithdrawalBonus
        // which increases the reward by 100 and triggers a withdrawal; to create a scenario where withdrawReward is called and leaves state,
        // we will first set claimedBonus[recipient] = false by using a fresh address and then call getFirstWithdrawalBonus via that recipient.

        // fund the contract so withdrawReward can send ETH
        vm.deal(address(c), initialReward + 200); // ensure enough balance

        // Use a helper account to call getFirstWithdrawalBonus for recipient to create a reward entry and then cause a withdraw
        // We will call getFirstWithdrawalBonus from recipient itself (prank) so it acts as recipient
        vm.startPrank(recipient);
        // calling getFirstWithdrawalBonus will add 100 to rewardsForA[recipient], then call withdrawReward(recipient)
        // which should withdraw and then (in the reference) clear the reward to zero. For the mutant, withdrawReward won't clear it.
        try c.getFirstWithdrawalBonus(recipient) {
            // call succeeded
        } catch {
            // If it reverts for any reason, that's outside our targeted property; just stop prank
        }
        vm.stopPrank();

        // Now call withdrawReward(recipient) again to observe whether the reward was cleared on the previous withdraw.
        // If reference behaved correctly, there is nothing to pay and rewardsForA[recipient] == 0. If mutant left state, it may be > 0.
        // withdrawReward is payable in effect (sends out ETH), ensure contract has funds
        vm.deal(address(c), 1);

        // Wrap call in try/catch to satisfy difference observation requirement if needed, but we will observe via public getter
        // The only public available observation is the auto getter for any public variable. However rewardsForA is private in the contract.
        // But SmartFix exposes no getter for rewardsForA. We therefore must observe outcome via address(c).balance change or revert behavior.
        // We will observe address(c).balance before and after calling withdrawReward(recipient):
        // - In the reference, after first getFirstWithdrawalBonus the contract paid out the bonus and cleared rewards; a second withdrawReward should attempt to send 0 and succeed without changing balance.
        // - In the mutant, the first getFirstWithdrawalBonus's withdraw would have sent funds but not cleared rewards; the second withdrawReward will send again and thus reduce contract balance by the outstanding amount.

        uint256 balBefore = address(c).balance;
        bool ok;
        try c.withdrawReward(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balAfter = address(c).balance;

        // General rule (single assertion): After calling withdrawReward(recipient) the contract's balance does not decrease (i.e., no additional funds are paid) when there should be no outstanding reward remaining; the reference ensures this for all inputs, the mutant will have balance decreased for some inputs.
        // We assert that the contract balance did not decrease as a result of the second withdraw attempt.
        assertTrue(balAfter >= balBefore);
    }
}

