        // keep initialReward bounded to a reasonable range so value transfers won't overflow EVM balances
        vm.assume(recipient != address(0));
        initialReward = bound(initialReward, 0, 1 ether);

        // fund this test contract so C can send ether out when withdrawReward is called
        vm.deal(address(this), 2 ether);

        // Arrange: directly manipulate rewards by calling getFirstWithdrawalBonus which adds 100
        // but to create an arbitrary prior reward we will simulate by first sending ether to C's rewards mapping
        // We cannot write private mapping, so we use the public flows: call getFirstWithdrawalBonus to set claimedBonus false->true
        // Then we top-up rewardsForA by making the recipient be this contract and performing a withdraw that uses the stored amount.
        // To reliably set an arbitrary reward amount we instead use the following approach:
        // 1) We will ensure the contract's rewardsForA[recipient] equals initialReward by calling getFirstWithdrawalBonus only if needed
        //    but since getFirstWithdrawalBonus adds exactly 100, we instead rely on the fuzz domain including small values.
        // Simpler: we will target the observable property after calling withdrawReward: the reference clears rewards to 0.

        // To deposit the desired amount into rewardsForA[recipient], we exploit getFirstWithdrawalBonus which increments by 100 only
        // so we create a scenario where initialReward is exactly 100 (the fuzzer can choose this) OR 0.
        // Keep domain wide but only assert the universal property over all recipients and initialReward values we can set via public API.

        // Use two cases to prepare rewardsForA[recipient]: if initialReward >= 100, we'll call getFirstWithdrawalBonus to add 100
        // and then treat the rest as already present by assuming the fuzzer selected initialReward in {0,100} via bounding.
        // To keep the admissible domain wide while still achievable by the public API, restrict initialReward to {0,100}.
        vm.assume(initialReward == 0 || initialReward == 100);

        // If initialReward == 100, call getFirstWithdrawalBonus to set rewardsForA[recipient] += 100 and then call withdrawReward
        // We need the contract to have Ether to send out amountToWithdraw, so fund C.
        vm.deal(address(c), 2 ether);

        if (initialReward == 100) {
            // calling getFirstWithdrawalBonus will add 100 to rewardsForA[recipient] and immediately withdraw and set claimedBonus
            // but withdrawReward will send ether to recipient; ensure recipient can receive funds: if recipient is a contract with fallback revert,
            // the call would revert; to keep domain admissible, require recipient to be an EOA (no code)
            vm.assume(recipient.code.length == 0);

