contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker initial balance to fund reentrant attack, and the recipient address
    function testFuzz_property(address attackerAddr, uint256 attackerFund) public {
        // keep attackerFund within reasonable bounds so vm.deal works and doesn't overflow
        attackerFund = bound(attackerFund, 0, 1 ether);
        // attacker must be nonzero
        vm.assume(attackerAddr != address(0));

        // deploy a reentrant attacker that will reenter withdrawReward when receiving funds
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund attacker so it can receive and have ETH for calling if needed
        vm.deal(address(attacker), attackerFund);

        // Prepare rewardsForA by calling getFirstWithdrawalBonus on the attacker address
        // This will credit rewardsForA[attacker] += 100 and then call withdrawReward(attacker)
        // On the correct contract, the nonReentrant guard prevents reentrancy during the external call,
        // so the attacker cannot reenter and cause extra drains. On the buggy contract the attacker
        // reenters during the external call and can trigger additional withdraws altering c balance change.

        // Measure balance before
        uint256 before = address(c).balance;

        // Call getFirstWithdrawalBonus targeting the attacker contract which will try to reenter
        // Use try/catch to allow both behaviors (success or revert) but we observe balance change
        try c.getFirstWithdrawalBonus(address(attacker)) {
            // do nothing
        } catch {
            // ignore revert; still will observe balance change
        }

        uint256 after = address(c).balance;

        // On the correct contract, withdrawReward sends exactly the credited 100 wei (from rewardsForA)
        // so the contract balance should have decreased by exactly 100 (or by 0 if there was no balance to send).
        // However, the reference contract C credits 100 to rewardsForA and immediately withdraws it,
        // so the net decrease should be exactly 100 wei if c had at least 100 wei. To keep the admissible domain
        // wide and avoid assumptions about initial funding, we assert the change is at most 100 wei in magnitude
        // (i.e., c.balance decreased by <= 100). The buggy modifier allowing reentrancy can cause attacker to
        // drain more, making the decrease > 100.

        // Compute decrease (clamp to before >= after to avoid underflow)
        uint256 decrease = before >= after ? before - after : 0;

        // The general rule: for all inputs, on the correct contract decrease <= 100
        // (since only the single credited 100 should be sent out). The buggy mutant can make decrease > 100.
        assertTrue(decrease <= 100);
