pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an address that will act as the recipient and an initial balance to fund that recipient helper
    function testFuzz_property(address recipient, uint256 fund) public {
        // keep fund reasonable but wide
        fund = bound(fund, 0, 1 ether);

        // Deploy a helper that will revert on receiving funds to simulate a failing external call.
        // This adversarial callee will cause withdrawReward's low-level call to fail.
        Reverter rev = new Reverter();

        // fund the reverter so it can be used as recipient (not strictly necessary for revert, but safe)
        vm.deal(address(rev), fund);

        // Drive the contract through the entry point with the adversarial callee's address
        // The fuzzer still controls the provided recipient address via `recipient` param.
        // Use the reverter address as the actual recipient to provoke the failing low-level call.
        address target = address(rev);

        // Call the function under test. We don't expect it to revert on the reference contract.
        bool ok;
        try c.getFirstWithdrawalBonus(target) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after the call completes (whether it reverted or not),
        // the reference contract guarantees rewardsForA[target] == 0. We observe this via the
        // auto-generated getter for the (private) mapping is NOT available; however the problem
        // statement indicates a public getter named getFirstWithdrawalBonus() differs —
        // since the source exposes no getter for rewardsForA, we instead observe behavior via
        // address(c).balance change: in the reference, any credited bonus (100) is immediately
        // withdrawn, so c's balance should remain 0 after the call; in the mutant, if the
        // external transfer fails, the reward remains credited and c retains funds (balance > 0).
        // Thus we assert that address(c).balance == 0 which the correct contract satisfies for all inputs,
        // while the mutant (which adds 0 instead of 100 but leaves accounting inconsistent on failed transfer)
        // can end up with address(c).balance != 0 for some inputs (the failing recipient).

        assertTrue(address(c).balance == 0);
    }
}

// Adversarial helper that always reverts on receiving Ether
contract Reverter {
    fallback() external payable {
        revert("no funds");
    }
    receive() external payable {
        revert("no funds");
    }
}
